content.text:
                return "PROTOCOL_VIOLATION"
        return None

    def frame_crypto(self, fr, lvl, fi):
        off = fr[1]
        data = fr[2]
        end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        self.snapshot_cstore(lvl)
        cs = self.cs[lvl]
        if end > self.clim:
            return "CRYPTO_BUFFER_EXCEEDED"
        if end > cs.highest:
            cs.highest = end
        if data:
            if not store_insert(cs.ivs, off, data, self.reject, self.journal):
                return "PROTOCOL_VIOLATION"
            chunk = store_deliver(cs.ivs, len(cs.contig))
            if chunk:
                cs.contig += chunk
        return None

    def _stream_common(self, sid, fi, want_bidi):
        """Direction and stream-count checks; returns (stream, error)."""
        mod = sid & 3
        if want_bidi:
            if mod != 0:
                return None, "STREAM_STATE_ERROR"
            limit = self.msb
        else:
            if mod != 0 and mod != 2:
                return None, "STREAM_STATE_ERROR"
            limit = self.msb if mod == 0 else self.msu
        if sid // 4 + 1 > limit:
            return None, "STREAM_LIMIT_ERROR"
        st = self.get_stream(sid)
        self.snapshot_stream(st)
        return st, None

    def frame_stream(self, fr, fi):
        sid = fr[1]
        off = fr[2]
        data = fr[3]
        fin = fr[4]
        st, err = self._stream_common(sid, fi, False)
        if st is None:
            return err
        end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        final = st.final
        if final is not None and (end > final or (fin and end != final)):
            return "FINAL_SIZE_ERROR"
        if fin and end < st.highest:
            return "FINAL_SIZE_ERROR"
        if end > self.msd:
            return "FLOW_CONTROL_ERROR"
        if end > st.highest:
            delta = end - st.highest
            if self.received_total + delta > self.max_data:
                return "FLOW_CONTROL_ERROR"
            st.highest = end
            self.received_total += delta
        if not st.reset:
            if data and not store_insert(st.ivs, off, data, self.reject,
                                         self.journal):
                return "PROTOCOL_VIOLATION"
            chunk = store_deliver(st.ivs, len(st.delivered))
            if chunk:
                st.delivered += chunk
        if fin:
            st.final = end
        return None

    def frame_reset(self, fr, fi):
        sid = fr[1]
        size = fr[2]
        st, err = self._stream_common(sid, fi, False)
        if st is None:
            return err
        final = st.final
        if final is not None and final != size:
            return "FINAL_SIZE_ERROR"
        if size < st.highest:
            return "FINAL_SIZE_ERROR"
        if size > self.msd:
            return "FLOW_CONTROL_ERROR"
        if size > st.highest:
            delta = size - st.highest
            if self.received_total + delta > self.max_data:
                return "FLOW_CONTROL_ERROR"
            st.highest = size
            self.received_total += delta
        st.final = size
        st.reset = True
        return None

    def frame_stop(self, fr, fi):
        sid = fr[1]
        st, err = self._stream_common(sid, fi, True)
        if st is None:
            return err
        st.stopped = True
        return None

    # ---- output ---------------------------------------------------------

    def result(self):
        results = self.results
        results.sort(key=lambda r: (r[0], r[1]))
        pkts = []
        for (ei, pi, status, reason, at, frame) in results:
            pkts.append({"event": ei, "packet": pi, "status": status,
                         "reason": reason, "at_ms": at, "frame": frame})
        if self.state == "open":
            conn = {"state": "open", "code": None, "at_ms": None,
                    "source": None, "peer_code": None,
                    "last_activity_ms": self.last_activity}
        else:
            src = {"event": self.source[0], "packet": self.source[1],
                   "frame": self.source[2]}
            conn = {"state": self.state, "code": self.code,
                    "at_ms": self.at_ms, "source": src,
                    "peer_code": self.peer_code,
                    "last_activity_ms": self.last_activity}
        streams = []
        for sid in sorted(self.streams):
            st = self.streams[sid]
            streams.append({"id": sid, "highest": st.highest,
                            "final_size": st.final, "reset": st.reset,
                            "stopped": st.stopped,
                            "delivered_hex": bytes(st.delivered).hex()})
        crypto = []
        for lvl in CLEVELS:
            cs = self.cs[lvl]
            crypto.append({"level": lvl, "highest": cs.highest,
                           "contiguous_hex": bytes(cs.contig).hex()})
        return {"id": self.id, "packets": pkts, "connection": conn,
                "keys": {"I": self.keys["I"], "H": self.keys["H"],
                         "Z": self.keys["Z"], "A": self.keys["A"]},
                "received_total": self.received_total,
                "streams": streams, "crypto": crypto}


